async function studentLoginWithCode(value){const token=String(value||'').trim().toUpperCase();if(!/^[A-Z2-9]{17}$/.test(token)){toast('كود دخول الطالب غير صحيح. امسح كود الدخول العشوائي الجديد.');return}try{sessionStorage.setItem(AUTH_SESSION_KEY,'1');$('#auth-error').textContent='جاري فتح ملف الطالب…';if(cloudAuth.currentUser&&!cloudAuth.currentUser.isAnonymous)await cloudAuth.signOut();if(!cloudAuth.currentUser||!cloudAuth.currentUser.isAnonymous)await cloudAuth.signInAnonymously();const snap=await cloudDb.collection('studentPortal').doc(token).get();if(!snap.exists)throw Error('code-not-found');let paymentData=null;try{const paymentSnap=await cloudDb.collection('studentPaymentPortal').doc(token).get();if(paymentSnap.exists)paymentData=paymentSnap.data()}catch{}renderPortal(snap.data(),paymentData);$('#auth-error').textContent='';$('#portal-code').value='';$('#auth-gate').hidden=true;$('#student-portal-page').hidden=false;document.body.classList.add('auth-student');stopAll()}catch(error){sessionStorage.removeItem(AUTH_SESSION_KEY);$('#auth-error').textContent=error.message==='code-not-found'?'الكود مش متسجل. اتأكد إن ده كود دخول الطالب الجديد.':'مقدرناش نفتح الملف. اتأكد من الإنترنت وجرب تاني.';console.error('Student portal sign-in failed',error)}}
async function activateStaff(user){if(!user||user.isAnonymous||currentUser?.uid===user.uid&&currentRole)return;currentUser=user;{const cachedRole=localStorage.getItem(KEY+'-role-'+user.uid);let cachedDb=null;try{cachedDb=JSON.parse(localStorage.getItem(KEY+'-user-'+user.uid)||'null')}catch{}if(cachedDb&&['admin','assistant'].includes(cachedRole)&&cachedDb.students?.length){currentRole=cachedRole;db={...blank(),...cachedDb,payments:cachedRole==='admin'?(cachedDb.payments||[]):[]};if(!Array.isArray(db.sessions))db.sessions=[];if(!Array.isArray(db.finance))db.finance=[];cloudLoaded=false;showStaffShell(cachedRole,'بنحدّث البيانات من Firebase…');init();go('home');$('#auth-error').textContent='';verifyStaffRole(user,cachedRole);syncCloudNow();return}}$('#auth-error').textContent='بنتأكد من صلاحيات الحساب…';try{const staff=await withTimeout(cloudDb.collection('staff').doc(user.uid).get(),25000,'staff-timeout');if(!staff.exists||!['admin','assistant'].includes(staff.data().role)){currentUser=null;await cloudAuth.signOut();throw Error('role-not-set')}const role=staff.data().role;currentRole=role;localStorage.setItem(KEY+'-role-'+user.uid,role);await loadStaffCloud(role);$('#auth-gate').hidden=true;$('#student-portal-page').hidden=true;document.body.classList.remove('auth-student');document.body.classList.add('auth-staff');const paymentNav=$('.nav[data-page="payments"]');if(paymentNav)paymentNav.hidden=role!=='admin';$$('.admin-only').forEach(item=>item.hidden=role!=='admin');const profilePayments=$('#profile-payments')?.closest('.profile-section');if(profilePayments)profilePayments.hidden=role!=='admin';$('#signed-in-label').textContent=role==='admin'?'المدرس · البيانات متزامنة':'المساعد · البيانات متزامنة';init();go('home');await syncCloudNow();$('#auth-error').textContent=''}catch(error){const cachedRole=localStorage.getItem(KEY+'-role-'+user.uid),cachedDb=JSON.parse(localStorage.getItem(KEY+'-user-'+user.uid)||'null');if(!navigator.onLine&&cachedDb&&['admin','assistant'].includes(cachedRole)){currentRole=cachedRole;db={...blank(),...cachedDb,payments:cachedRole==='admin'?(cachedDb.payments||[]):[]};document.body.classList.add('auth-staff');$('#auth-gate').hidden=true;const paymentNav=$('.nav[data-page="payments"]');if(paymentNav)paymentNav.hidden=cachedRole!=='admin';$$('.admin-only').forEach(item=>item.hidden=cachedRole!=='admin');const profilePayments=$('#profile-payments')?.closest('.profile-section');if(profilePayments)profilePayments.hidden=cachedRole!=='admin';$('#signed-in-label').textContent='وضع بدون إنترنت · المزامنة هتتم بعد الاتصال';init();return}if(error.message==='role-not-set')$('#auth-error').textContent='الحساب لسه ما اتحددش كمدرس أو مساعد. لازم يتضاف له الدور من إعدادات Firebase.';else if(error.message.startsWith('collection-read:'))$('#auth-error').textContent='دخول الحساب تم، لكن Firebase منع قراءة مجموعة '+error.message.slice('collection-read:'.length)+'. غالبًا قواعد الحماية المنشورة محتاجة تحديث.';else if(error.code==='permission-denied')$('#auth-error').textContent='Firebase منع قراءة صلاحيات الحساب. راجع إن قواعد الحماية منشورة وإن الحساب له دور مساعد.';else if(String(error.message||'').includes('timeout')){currentUser=null;currentRole='';$('#auth-error').textContent='النت بطيء والتحميل خد وقت طويل. اتأكد من الإنترنت ودوس تسجيل الدخول تاني.'}else $('#auth-error').textContent='تعذر تحميل بيانات Firebase. اتأكد من الإنترنت وجرب مرة تانية.';console.error('Staff access denied',error)}}
function withTimeout(promise,ms,label){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label||'timeout')),ms)})]).finally(()=>clearTimeout(timer))}
