let livePickedStudentId='';function liveClassRecords(session=activeSession()){if(!session)return[];return sessionRecords(session).map(r=>({record:r,student:db.students.find(s=>s.id===r.studentId)})).filter(x=>x.student)}function renderLiveClass(){const banner=$('#live-class-banner'),panel=$('#live-class-panel');if(!banner)return;const schedule=activeSession();if(!schedule){banner.hidden=true;panel.hidden=true;livePickedStudentId='';return}banner.hidden=false;$('#live-class-toggle').textContent='الآن حصة '+(CLASSES[Number(schedule.classId)]||'')+' · بدأت '+clockTime(schedule.startedAt);const list=liveClassRecords(schedule),remaining=list.filter(x=>!x.record.randomAsked).length;$('#live-draw-counter').textContent=list.length?'المتبقي في الدورة: '+remaining+' من '+list.length+' طالب':'مفيش طلاب في الدورة لسه.';$('#live-class-students').innerHTML=list.length?list.map(({student,record})=>'<button type="button" class="live-class-student" data-live-profile="'+esc(student.id)+'"><span class="avatar">'+esc(student.name.trim()[0]||'؟')+'</span><span><strong>'+esc(student.name)+'</strong><small>حاضر · '+esc(record.time||'')+' · '+(HW_LABELS[record.homework]||'الواجب لسه متسجلش')+'</small></span><b>الملف ←</b></button>').join(''):'<div class="profile-empty">لسه مفيش طالب سجّل حضوره في الحصة دي.</div>';$('#live-random').disabled=!list.length;const picked=list.find(x=>x.student.id===livePickedStudentId);$('#live-picked-student').hidden=!picked;if(picked){$('#live-picked-name').textContent=picked.student.name;let hw=$('#live-picked-homework');if(!hw){hw=document.createElement('div');hw.id='live-picked-homework';$('#live-picked-name').after(hw)}hw.innerHTML=homeworkButtons(picked.record.id,picked.record.homework);bindHomework(hw)}$$('[data-live-profile]').forEach(button=>button.onclick=()=>showProfile(button.dataset.liveProfile))}function renderStudentAnswers(){if(!activeProfileId)return;const events=[];for(const [date,records]of Object.entries(db.attendance||{})){for(const record of records||[]){if(record.studentId!==activeProfileId)continue;for(const response of record.responses||[]){const schedule=[...db.schedules,...db.scheduleHistory].find(item=>item.id===record.scheduleId),ses=record.sessionId&&db.sessions.find(item=>item.id===record.sessionId);events.push({date,time:response.time||record.time||schedule?.time||'',status:response.status,rating:response.rating,scheduleName:ses?sessionName(ses):schedule?(WEEKDAYS[Number(schedule.day)]+' · '+schedule.time):'الحصة',createdAt:response.createdAt||''})}}}events.sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));$('#profile-answers').innerHTML=events.length?events.map(item=>'<div class="profile-row"><strong>'+esc(prettyDate(item.date))+' · '+esc(item.scheduleName)+'</strong><span class="answer-rating">'+esc(item.status)+' · '+esc(String(item.rating))+' من 10</span><small>الساعة '+esc(item.time||'—')+'</small></div>').join(''):'<div class="profile-empty">لسه مفيش إجابات أو مشاركات مسجلة.</div>'}function saveLiveAnswer(answered){const schedule=activeSession();if(!schedule||!livePickedStudentId)return;const selected=livePickedStudentId,rating=answered?$('#live-answer-rating').value:'0';if(answered&&rating===''){toast('اختار تقييم الإجابة من 10 الأول.');return}const record=sessionRecords(schedule).find(r=>r.studentId===selected);if(!record){toast('مش لاقي تسجيل حضور الطالب في الحصة دي.');return}if(!Array.isArray(record.responses))record.responses=[];record.responses.push({id:crypto.randomUUID?.()||String(Date.now()),status:answered?'جاوب':'مجاوبش',rating:Number(rating),time:new Date().toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'}),createdAt:new Date().toISOString()});save();if(activeProfileId===selected)renderStudentAnswers();$('#live-answer-note').textContent='اتسجلت مشاركة الطالب وتقييمها في ملفه.';livePickedStudentId='';$('#live-picked-student').hidden=true;renderLiveClass();toast('اتسجلت الإجابة وتقييمها في ملف الطالب.')}function setupLiveClass(){const toggle=$('#live-class-toggle');toggle.onclick=()=>{const panel=$('#live-class-panel');panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden))};$('#live-random').onclick=()=>{const list=liveClassRecords();if(!list.length){toast('مفيش طالب سجل حضوره في الحصة لسه.');return}let candidates=list.filter(x=>!x.record.randomAsked),restarted=false;if(!candidates.length){for(const item of list)delete item.record.randomAsked;candidates=list;restarted=true}const chosen=candidates[Math.floor(Math.random()*candidates.length)];chosen.record.randomAsked=true;save();livePickedStudentId=chosen.student.id;$('#live-picked-student').hidden=false;$('#live-picked-name').textContent=chosen.student.name;$('#live-answer-rating').value='';$('#live-answer-note').textContent=restarted?'كل المجموعة اتسألت؛ بدأنا دورة جديدة من الأول.':'';renderLiveClass();$('#live-picked-student').scrollIntoView({block:'nearest',behavior:'smooth'})};$('#live-answer-yes').onclick=()=>saveLiveAnswer(true);$('#live-answer-no').onclick=()=>saveLiveAnswer(false);$('#live-answer-rating').innerHTML='<option value="">اختار التقييم</option>'+Array.from({length:11},(_,i)=>'<option value="'+i+'">'+i+' من 10</option>').join('')}
