function normalizeStudentSearch(value){return String(value||'').trim().toLocaleLowerCase('ar-EG').replace(/[ًٌٍَُِّْـ]/g,'')}
function findHomeStudents(query){const q=normalizeStudentSearch(query);if(!q)return[];return db.students.filter(s=>normalizeStudentSearch(s.name).includes(q)||normalizeStudentSearch(s.code).includes(q)||normalizeStudentSearch(s.portalToken).includes(q))}
function renderHomeSearch(){const box=$('#home-student-search-results'),input=$('#home-student-query');if(!box||!input)return;const q=input.value.trim();if(!q){box.innerHTML='<div class="profile-empty">اكتب اسم الطالب أو كوده علشان تلاقي ملفه.</div>';return}const matches=findHomeStudents(q);box.innerHTML=matches.length?matches.map(s=>'<button type="button" class="home-student-result" data-home-student="'+esc(s.id)+'"><strong>'+esc(s.name)+'</strong><span>'+esc(CLASSES[Number(s.classId)]||'')+(s.code?' · '+esc(s.code):'')+'</span></button>').join(''):'<div class="profile-empty">مفيش طالب مطابق للبحث ده.</div>';$$('[data-home-student]').forEach(button=>button.onclick=()=>showProfile(button.dataset.homeStudent))}
