async function compressStudentPhoto(file){if(!file||!file.type.startsWith('image/'))throw Error('not-image');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=reader.result};reader.onerror=reject;reader.readAsDataURL(file)});const scale=Math.min(1,512/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.72)}
function money(value){return `${Number(value||0).toLocaleString('ar-EG')} ج.م`}
function paymentsForStudent(studentId,month){return db.payments.filter(p=>p.studentId===studentId&&p.month===month)}
function monthlyPaid(studentId,month){return paymentsForStudent(studentId,month).reduce((sum,p)=>sum+Number(p.amount||0),0)}
function renderPayments(){const host=$('#payment-students');if(!host)return;const month=$('#payment-month').value||dayKey().slice(0,7),classId=$('#payment-class-select').value||'0',students=db.students.filter(s=>String(s.classId)===String(classId)).sort((a,b)=>a.name.localeCompare(b.name,'ar'));host.innerHTML=students.length?students.map(s=>{const paid=monthlyPaid(s.id,month);return `<div class="payment-student-row"><div class="payment-student-info"><span class="avatar">${esc(s.name.trim()[0]||'؟')}</span><div><button type="button" class="student-profile-shortcut" data-profile-student="${esc(s.id)}">${esc(s.name)}</button><small>مدفوع الشهر ده: ${money(paid)}</small></div></div><input type="number" min="0.01" step="0.01" data-payment-amount placeholder="المبلغ بالجنيه" aria-label="مبلغ ${esc(s.name)}"><button type="button" class="primary" data-save-payment="${esc(s.id)}">حفظ الدفعة</button></div>`}).join(''):'<div class="empty-state"><b>مفيش طلاب في الصف ده لسه</b><small>سجّل الطلاب من صفحة الطلاب الأول.</small></div>';$$('[data-save-payment]').forEach(b=>b.onclick=()=>savePayment(b.dataset.savePayment,b.closest('.payment-student-row').querySelector('[data-payment-amount]')));if(!$('#payment-totals').hidden)renderPaymentTotals()}
function savePayment(studentId,input){const amount=Number(input.value),month=$('#payment-month').value;if(!month||!Number.isFinite(amount)||amount<=0){toast('اكتب مبلغ أكبر من صفر');return}db.payments.push({id:crypto.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2,7),studentId,month,amount,paidAt:new Date().toISOString()});save();renderPayments();if(activeProfileId===studentId)renderProfileRecords();toast('تم تسجيل الدفعة')}
function renderPaymentTotals(){const month=$('#payment-month').value||dayKey().slice(0,7),classId=String($('#payment-class-select').value||'0'),forMonth=db.payments.filter(p=>p.month===month),studentsByClass=new Map(db.students.map(s=>[s.id,String(s.classId)])),classTotal=forMonth.filter(p=>studentsByClass.get(p.studentId)===classId).reduce((sum,p)=>sum+Number(p.amount||0),0),allTotal=forMonth.reduce((sum,p)=>sum+Number(p.amount||0),0);$('#payment-class-total').textContent=money(classTotal);$('#payment-all-total').textContent=money(allTotal);$('#payment-class-breakdown').innerHTML=CLASSES.map((name,i)=>{const total=forMonth.filter(p=>studentsByClass.get(p.studentId)===String(i)).reduce((sum,p)=>sum+Number(p.amount||0),0);return `<div class="payment-breakdown-row"><span>${name}</span><strong>${money(total)}</strong></div>`}).join('')}
function scheduleVersions(){return [...db.scheduleHistory,...db.schedules.map(s=>({...s,effectiveTo:null}))]}
function addDateDays(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return dayKey(d)}
