let beepCtx=null;
function unlockBeep(){try{beepCtx=beepCtx||new(window.AudioContext||window.webkitAudioContext)();if(beepCtx.state==='suspended')beepCtx.resume()}catch{}}
function beep(ok=true){try{unlockBeep();const t=beepCtx.currentTime,o=beepCtx.createOscillator(),g=beepCtx.createGain(),len=ok?.12:.32;o.type='square';o.frequency.setValueAtTime(ok?1760:330,t);if(!ok)o.frequency.setValueAtTime(260,t+.16);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.22,t+.01);g.gain.setValueAtTime(.22,t+len-.03);g.gain.exponentialRampToValueAtTime(.0001,t+len);o.connect(g);g.connect(beepCtx.destination);o.start(t);o.stop(t+len+.02)}catch{}try{navigator.vibrate?.(ok?60:[90,60,90])}catch{}}
