function loadScriptOnce(src){return new Promise((ok,fail)=>{if(document.querySelector('script[src="'+src+'"]')){ok();return}const el=document.createElement('script');el.src=src;el.onload=()=>ok();el.onerror=()=>fail(new Error('load '+src));document.head.appendChild(el)})}
async function downloadReportPdf(html,filename){toast('بنجهّز ملف الـ PDF…');try{await Promise.all([loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'),loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js')]);const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-10000px;top:0;width:794px;height:1123px;border:0';document.body.appendChild(frame);frame.contentDocument.open();frame.contentDocument.write(html.replace(/<script[\s\S]*?<\/script>/g,'').replace(/<button class="print"[\s\S]*?<\/button>/,''));frame.contentDocument.close();await new Promise(r=>setTimeout(r,250));try{await frame.contentDocument.fonts.ready}catch{}const body=frame.contentDocument.body;body.style.cssText='margin:0;padding:34px 38px;width:794px;background:#fff';const canvas=await window.html2canvas(body,{scale:2,backgroundColor:'#ffffff',windowWidth:794,width:794,height:body.scrollHeight});frame.remove();const pdf=new window.jspdf.jsPDF({unit:'pt',format:'a4'}),pageW=pdf.internal.pageSize.getWidth(),pageH=pdf.internal.pageSize.getHeight(),pxPerPage=Math.floor(canvas.width*pageH/pageW);for(let y=0,page=0;y<canvas.height;y+=pxPerPage,page++){const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=Math.min(pxPerPage,canvas.height-y);slice.getContext('2d').drawImage(canvas,0,y,canvas.width,slice.height,0,0,canvas.width,slice.height);if(page)pdf.addPage();pdf.addImage(slice.toDataURL('image/jpeg',.92),'JPEG',0,0,pageW,slice.height*pageW/canvas.width)}pdf.save(filename);toast('اتنزّل ملف الـ PDF')}catch(error){console.error('PDF failed',error);const w=window.open('','_blank');if(!w){toast('مقدرناش نعمل الـ PDF. اتأكد من الإنترنت وجرب تاني.');return}w.document.open();w.document.write(html);w.document.close()}}
let sessionTimer=0;
function tickSession(){const session=activeSession();if(!session)return;const deadline=sessionDeadline(session);if(deadline&&Date.now()>=deadline.getTime()){endSession(session,{auto:true,at:deadline});return}const el=$('#session-timer');if(el){const sec=Math.max(0,Math.floor((Date.now()-new Date(session.startedAt).getTime())/1000)),pad=n=>String(n).padStart(2,'0');el.textContent=(sec>=3600?Math.floor(sec/3600)+':':'')+pad(Math.floor(sec/60)%60)+':'+pad(sec%60)}const auto=$('#session-autoclose');if(auto){if(!deadline)auto.textContent='هتقفل لوحدها بعد ساعة وربع من أول مسح';else{const left=Math.max(0,Math.floor((deadline.getTime()-Date.now())/1000));auto.textContent='هتقفل لوحدها بعد '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0');auto.classList.toggle('soon',left<600)}}}
// ---------- نقل طلاب لصف (مع أو من غير تسجيل حضور) ----------
