function openClassMove(mode){if(activeStudentsClass==='')return;classMoveMode=mode;const name=CLASSES[Number(activeStudentsClass)]||'',ses=latestClassSession(activeStudentsClass);$('#class-move-title').textContent=(mode==='attend'?'نقل مع تسجيل الحضور · ':'نقل لـ ')+name;$('#class-move-help').textContent=mode==='attend'?(ses?'الطالب هيتنقل للصف ده ويتسجل حاضر في '+(ses.endedAt?'آخر حصة':'الحصة الشغالة')+' ('+prettyDate(ses.date)+' · '+clockTime(ses.startedAt)+').':'مفيش حصة للصف ده لسه؛ الطالب هيتنقل بس.'):'امسح كود الطالب أو اكتب اسمه، وهيتنقل للصف ده على طول.';$('#class-move-log').innerHTML='';$('#class-move-input').value='';$('#class-move-suggest').innerHTML='';$('#class-move-dialog').showModal();unlockBeep();$('#class-move-camera').click()}
function classMoveStudent(student){const target=activeStudentsClass;if(target==='')return;const moved=moveStudentToClass(student,target);let note=moved?'اتنقل لـ '+(CLASSES[Number(target)]||''):'هو أصلًا في الصف ده';if(classMoveMode==='attend'){const ses=latestClassSession(target);if(ses){const row=markPresent(student,ses,{late:!!ses.endedAt,manual:true});note+=row?' · اتسجل حاضر':' · كان متسجل حاضر قبل كده'}else note+=' · مفيش حصة للصف ده'}save();render();beep(true);$('#class-move-log').insertAdjacentHTML('afterbegin','<div class="absent-item"><span class="avatar">'+esc(student.name.trim()[0]||'؟')+'</span><div><strong>'+esc(student.name)+'</strong><small>'+esc(note)+'</small></div></div>');$('#class-move-input').value='';$('#class-move-suggest').innerHTML='';toast(student.name+': '+note)}
function classMoveByValue(value){const raw=String(value||'').trim();if(!raw)return;const st=db.students.find(s=>s.code===raw.toUpperCase());if(st){classMoveStudent(st);return}const matches=findStudentsByQuery(raw,'');if(matches.length===1&&nameKey(matches[0].name)===nameKey(raw)){classMoveStudent(matches[0]);return}beep(false);toast(matches.length?'اختار الطالب من القايمة.':'مفيش طالب بالكود أو الاسم ده.')}
