function setupSessions(){$('#start-session-btn').onclick=startSession;$('#end-session-btn').onclick=()=>endSession();$('#cancel-session-btn').onclick=cancelSession;$('#close-session-dialog').onclick=()=>$('#session-dialog').close();$('#session-dialog-ok').onclick=()=>$('#session-dialog').close();$('#session-pdf-btn').onclick=()=>resultSessionId&&sessionReport(resultSessionId);$('#session-result-class').onchange=e=>{const ses=db.sessions.find(x=>x.id===resultSessionId);if(!ses)return;const name=CLASSES[Number(e.target.value)]||'';if(!confirm('تغيّر صف الحصة دي لـ '+name+'؟ الغياب هيتحسب من جديد على طلاب '+name+'.')){e.target.value=String(ses.classId);return}changeSessionClass(ses,e.target.value);showSessionResult(ses.id);toast('الحصة بقت لـ '+name)};$('#late-add-input').oninput=e=>{const ses=db.sessions.find(x=>x.id===resultSessionId);renderSuggest($('#late-add-suggest'),e.target.value,ses?.classId,st=>ses&&addLateStudent(ses,st))};$('#late-add-form').onsubmit=e=>{e.preventDefault();const ses=db.sessions.find(x=>x.id===resultSessionId);if(!ses)return;const raw=$('#late-add-input').value.trim(),st=db.students.find(s=>s.code===raw.toUpperCase())||(()=>{const m=findStudentsByQuery(raw,ses.classId);return m.length===1?m[0]:null})();if(st)addLateStudent(ses,st);else toast('اختار الطالب من القايمة.')};$('#manual-code').oninput=e=>renderSuggest($('#manual-suggest'),e.target.value,activeSession()?.classId,st=>{attendStudent(st,{manual:true});$('#manual-code').value='';$('#manual-suggest').innerHTML=''});$('#camera-btn').addEventListener('click',unlockBeep);$('#class-move-attend-btn').onclick=()=>openClassMove('attend');$('#class-move-only-btn').onclick=()=>openClassMove('move');$('#class-move-close').onclick=closeClassMove;$('#class-move-done').onclick=closeClassMove;$('#class-move-dialog').onclose=()=>{stopAll();renderStudents()};$('#class-move-camera').onclick=()=>startScan($('#class-move-video'),$('#class-move-scanner'),$('#class-move-placeholder'),$('#class-move-camera'),$('#class-move-stop'),v=>{classMoveByValue(v)});$('#class-move-stop').onclick=closeClassMoveCamera;$('#class-move-form').onsubmit=e=>{e.preventDefault();classMoveByValue($('#class-move-input').value)};$('#class-move-input').oninput=e=>renderSuggest($('#class-move-suggest'),e.target.value,'',classMoveStudent);clearInterval(sessionTimer);sessionTimer=setInterval(tickSession,1000);$('#attendance-success').onclick=e=>{if(e.target.id==='attendance-success'||e.target.id==='attendance-success-close'){clearTimeout(attendanceNoticeTimer);$('#attendance-success').hidden=true}};renderSessionNotice()}
