function renderGuestChoice(extra,rec,ses,st){const from=CLASSES[Number(st.classId)]||'',to=CLASSES[Number(ses.classId)]||'',first=!sessionRecords(ses).some(r=>!r.guest);extra.innerHTML='<div class="class-switch-offer"><span><b>'+esc(st.name)+'</b> مش من المجموعة دي · مسجل في <b>'+esc(from)+'</b></span><div class="guest-actions"><button type="button" class="primary" data-guest="move">نقل الطالب للمجموعة دي</button><button type="button" class="secondary" data-guest="once">تسجيل حضوره المرة دي بس</button></div>'+(first?'<button type="button" class="text-btn" data-guest="switch">ولا الحصة دي أصلًا لـ '+esc(from)+'؟ غيّر صف الحصة</button>':'')+'</div>';clearTimeout(attendanceNoticeTimer);extra.querySelector('[data-guest="move"]').onclick=e=>{e.stopPropagation();moveGuestIntoSession(rec.id);guestChoiceDone(extra,'✓ '+esc(st.name)+' اتنقل لـ '+esc(to))};extra.querySelector('[data-guest="once"]').onclick=e=>{e.stopPropagation();guestChoiceDone(extra,'✓ اتسجل حضوره المرة دي بس · من مجموعة '+esc(from))};const sw=extra.querySelector('[data-guest="switch"]');if(sw)sw.onclick=e=>{e.stopPropagation();changeSessionClass(ses,st.classId);$('#attendance-success-message').textContent='تم تسجيل الطالب '+st.name;guestChoiceDone(extra,'✓ الحصة بقت لـ '+esc(from))}}
function moveGuestIntoSession(recordId){const rec=findAttendanceRecord(recordId),ses=rec&&db.sessions.find(x=>x.id===rec.sessionId),st=rec&&db.students.find(s=>s.id===rec.studentId);if(!rec||!ses||!st)return;moveStudentToClass(st,ses.classId);delete rec.guest;delete rec.fromClass;if(ses.endedAt)ses.absentIds=(ses.absentIds||[]).filter(id=>id!==st.id);save();render();if(activeProfileId===st.id)showProfile(st.id);toast(st.name+' اتنقل لـ '+(CLASSES[Number(ses.classId)]||''))}
