let unknownCode='';
function openUnknownCode(code){const session=activeSession();if(!session)return;unknownCode=code;$('#unknown-code-value').textContent=code;$('#unknown-code-class').textContent=CLASSES[Number(session.classId)]||'';$('#unknown-code-form').reset();$('#unknown-code-suggest').innerHTML='';$('#unknown-code-dialog').showModal();setTimeout(()=>$('#unknown-code-name').focus(),50)}
