function setupUnknownCode(){$('#unknown-code-close').onclick=()=>$('#unknown-code-dialog').close();$('#unknown-code-cancel').onclick=()=>$('#unknown-code-dialog').close();$('#unknown-code-name').oninput=e=>{unknownSuggest(e.target.value)};const unknownSuggest=v=>{renderSuggest($('#unknown-code-suggest'),v,activeSession()?.classId,st=>{if(st.code&&st.code!==unknownCode&&!confirm(st.name+' عنده كود '+st.code+'. تخليه ياخد الكود الجديد '+unknownCode+'؟'))return;attachCodeTo(st,unknownCode);finishUnknownCode(st);toast('اتربط الكود بـ '+st.name)});const host=$('#unknown-code-suggest'),items=[...host.children];items.sort((a,b)=>(a.textContent.includes('بدون كود')?0:1)-(b.textContent.includes('بدون كود')?0:1)).forEach(x=>host.appendChild(x));[...host.children].slice(3).forEach(x=>x.remove())};$('#unknown-code-form').onsubmit=e=>{e.preventDefault();const session=activeSession(),name=$('#unknown-code-name').value.trim();if(!session){toast('مفيش حصة شغالة.');return}if(!name){toast('اكتب اسم الطالب');return}if(db.students.some(s=>s.code===unknownCode)){toast('الكود ده اتربط بطالب بالفعل.');$('#unknown-code-dialog').close();return}const student={id:crypto.randomUUID?.()||String(Date.now()),name,phone:$('#unknown-code-phone').value.trim(),guardianPhone:$('#unknown-code-guardian').value.trim(),classId:String(session.classId),code:'',respectScore:null};attachCodeTo(student,unknownCode);db.students.push(student);finishUnknownCode(student);toast('اتسجل '+name+' في '+(CLASSES[Number(session.classId)]||'')+' وحضوره اتسجل')}}
function setupClassRename(){const btn=$('#rename-class-btn');if(!btn)return;btn.onclick=async()=>{if(activeStudentsClass==='')return;const index=Number(activeStudentsClass),old=CLASSES[index]||'',name=(prompt('اسم الصف الجديد:',isPlaceholderClass(old)?'':old)||'').trim();if(!name||name===old)return;if(!navigator.onLine){toast('تغيير اسم الصف محتاج إنترنت.');return}try{await renameClassSafely(index,name);render();toast('اسم الصف بقى '+name)}catch(err){toast(err.code==='exists'?'فيه صف تاني بنفس الاسم.':'مقدرناش نغيّر الاسم. جرب تاني.')}}}
