const HW_LABELS={done:'عمل الواجب',not:'ماعملش الواجب',none:'مفيش واجب'};
function homeworkBadge(v){return HW_LABELS[v]?'<span class="hw hw-'+v+'">'+HW_LABELS[v]+'</span>':''}
