function findAttendanceRecord(id){for(const rows of Object.values(db.attendance||{}))for(const r of rows||[])if(r.id===id)return r;return null}
function setHomework(recordId,value){const r=findAttendanceRecord(recordId);if(!r)return;r.homework=value;save();render();if(activeProfileId===r.studentId)renderProfileRecords();const open=$('#session-dialog').open&&db.sessions.find(x=>x.id===r.sessionId&&x.endedAt);if(open)showSessionResult(r.sessionId)}
