$('#range-form').onsubmit=async e=>{e.preventDefault();let from=Math.floor(+$('#range-from').value),to=Math.floor(+$('#range-to').value);if(!Number.isFinite(from)||!Number.isFinite(to)||from<1||to<1){toast('اكتب رقم البداية والنهاية.');return}if(from>to)[from,to]=[to,from];const picked=db.codes.filter(c=>{const n=codeNum(c.code);return Number.isFinite(n)&&n>=from&&n<=to}).sort((a,b)=>codeNum(a.code)-codeNum(b.code));if(!picked.length){toast('مفيش أكواد محفوظة في النطاق ده.');updateRangeHint();return}if(picked.length>1000){toast('النطاق كبير ('+picked.length+' كود). اختار 1000 كود أو أقل في كل ملف.');return}renderCodes(picked);try{await downloadCodesRangePdf(picked,from,to)}catch(error){console.error('codes pdf failed',error);toast('مقدرناش نعمل الـ PDF. اتأكد من الإنترنت وجرب تاني.')}};
